module Repeater(
  input         clock,
  input         reset,
  input         io_repeat,
  output        io_full,
  output        io_enq_ready,
  input         io_enq_valid,
  input  [2:0]  io_enq_bits_opcode,
  input  [2:0]  io_enq_bits_param,
  input  [2:0]  io_enq_bits_size,
  input  [4:0]  io_enq_bits_source,
  input  [27:0] io_enq_bits_address,
  input  [7:0]  io_enq_bits_mask,
  input         io_enq_bits_corrupt,
  input         io_deq_ready,
  output        io_deq_valid,
  output [2:0]  io_deq_bits_opcode,
  output [2:0]  io_deq_bits_param,
  output [2:0]  io_deq_bits_size,
  output [4:0]  io_deq_bits_source,
  output [27:0] io_deq_bits_address,
  output [7:0]  io_deq_bits_mask,
  output        io_deq_bits_corrupt
);
`ifdef RANDOMIZE_REG_INIT
  reg [31:0] _RAND_0;
  reg [31:0] _RAND_1;
  reg [31:0] _RAND_2;
  reg [31:0] _RAND_3;
  reg [31:0] _RAND_4;
  reg [31:0] _RAND_5;
  reg [31:0] _RAND_6;
  reg [31:0] _RAND_7;
`endif // RANDOMIZE_REG_INIT
  reg  full;
  reg [2:0] saved_opcode;
  reg [2:0] saved_param;
  reg [2:0] saved_size;
  reg [4:0] saved_source;
  reg [27:0] saved_address;
  reg [7:0] saved_mask;
  reg  saved_corrupt;
  assign io_full = full;
  assign io_enq_ready = io_deq_ready & ~full;
  assign io_deq_valid = io_enq_valid | full;
  assign io_deq_bits_opcode = full ? saved_opcode : io_enq_bits_opcode;
  assign io_deq_bits_param = full ? saved_param : io_enq_bits_param;
  assign io_deq_bits_size = full ? saved_size : io_enq_bits_size;
  assign io_deq_bits_source = full ? saved_source : io_enq_bits_source;
  assign io_deq_bits_address = full ? saved_address : io_enq_bits_address;
  assign io_deq_bits_mask = full ? saved_mask : io_enq_bits_mask;
  assign io_deq_bits_corrupt = full ? saved_corrupt : io_enq_bits_corrupt;
  always @(posedge clock) begin
    if (reset) begin
      full <= 1'h0;
    end else if (io_deq_ready & io_deq_valid & ~io_repeat) begin
      full <= 1'h0;
    end else begin
      full <= io_enq_ready & io_enq_valid & io_repeat | full;
    end
    if (io_enq_ready & io_enq_valid & io_repeat) begin
      saved_opcode <= io_enq_bits_opcode;
    end
    if (io_enq_ready & io_enq_valid & io_repeat) begin
      saved_param <= io_enq_bits_param;
    end
    if (io_enq_ready & io_enq_valid & io_repeat) begin
      saved_size <= io_enq_bits_size;
    end
    if (io_enq_ready & io_enq_valid & io_repeat) begin
      saved_source <= io_enq_bits_source;
    end
    if (io_enq_ready & io_enq_valid & io_repeat) begin
      saved_address <= io_enq_bits_address;
    end
    if (io_enq_ready & io_enq_valid & io_repeat) begin
      saved_mask <= io_enq_bits_mask;
    end
    if (io_enq_ready & io_enq_valid & io_repeat) begin
      saved_corrupt <= io_enq_bits_corrupt;
    end
  end
