module AMOALU(
  input  [7:0]  io_mask,
  input  [4:0]  io_cmd,
  input  [63:0] io_lhs,
  input  [63:0] io_rhs,
  output [63:0] io_out
);
  wire  max = io_cmd == 5'hd | io_cmd == 5'hf;
  wire  min = io_cmd == 5'hc | io_cmd == 5'he;
  wire  add = io_cmd == 5'h8;
  wire  logic_and = io_cmd == 5'ha | io_cmd == 5'hb;
  wire  logic_xor = io_cmd == 5'h9 | io_cmd == 5'ha;
  wire  _adder_out_mask_T_1 = ~io_mask[3];
  wire [31:0] _adder_out_mask_T_2 = {_adder_out_mask_T_1, 31'h0};
  wire [63:0] _adder_out_mask_T_3 = {{32'd0}, _adder_out_mask_T_2};
  wire [63:0] adder_out_mask = ~_adder_out_mask_T_3;
  wire [63:0] _adder_out_T = io_lhs & adder_out_mask;
  wire [63:0] _adder_out_T_1 = io_rhs & adder_out_mask;
  wire [63:0] adder_out = _adder_out_T + _adder_out_T_1;
  wire [4:0] _less_signed_T = io_cmd & 5'h2;
  wire  less_signed = _less_signed_T == 5'h0;
  wire  _less_T_17 = less_signed ? io_lhs[63] : io_rhs[63];
  wire  _less_T_18 = io_lhs[63] == io_rhs[63] ? io_lhs[63:32] < io_rhs[63:32] | io_lhs[63:32] == io_rhs[63:32] & io_lhs[
    31:0] < io_rhs[31:0] : _less_T_17;
  wire  _less_T_28 = less_signed ? io_lhs[31] : io_rhs[31];
  wire  _less_T_29 = io_lhs[31] == io_rhs[31] ? io_lhs[31:0] < io_rhs[31:0] : _less_T_28;
  wire  less = io_mask[4] ? _less_T_18 : _less_T_29;
  wire  _minmax_T = less ? min : max;
  wire [63:0] minmax = _minmax_T ? io_lhs : io_rhs;
  wire [63:0] _logic_T = io_lhs & io_rhs;
  wire [63:0] _logic_T_1 = logic_and ? _logic_T : 64'h0;
  wire [63:0] _logic_T_2 = io_lhs ^ io_rhs;
  wire [63:0] _logic_T_3 = logic_xor ? _logic_T_2 : 64'h0;
  wire [63:0] logic_ = _logic_T_1 | _logic_T_3;
  wire [63:0] _out_T_1 = logic_and | logic_xor ? logic_ : minmax;
  wire [63:0] out = add ? adder_out : _out_T_1;
  wire [7:0] wmask_lo_lo_lo = io_mask[0] ? 8'hff : 8'h0;
  wire [7:0] wmask_lo_lo_hi = io_mask[1] ? 8'hff : 8'h0;
  wire [7:0] wmask_lo_hi_lo = io_mask[2] ? 8'hff : 8'h0;
  wire [7:0] wmask_lo_hi_hi = io_mask[3] ? 8'hff : 8'h0;
  wire [7:0] wmask_hi_lo_lo = io_mask[4] ? 8'hff : 8'h0;
  wire [7:0] wmask_hi_lo_hi = io_mask[5] ? 8'hff : 8'h0;
  wire [7:0] wmask_hi_hi_lo = io_mask[6] ? 8'hff : 8'h0;
  wire [7:0] wmask_hi_hi_hi = io_mask[7] ? 8'hff : 8'h0;
  wire [63:0] wmask = {wmask_hi_hi_hi,wmask_hi_hi_lo,wmask_hi_lo_hi,wmask_hi_lo_lo,wmask_lo_hi_hi,wmask_lo_hi_lo,
    wmask_lo_lo_hi,wmask_lo_lo_lo};
  wire [63:0] _io_out_T = wmask & out;
  wire [63:0] _io_out_T_1 = ~wmask;
  wire [63:0] _io_out_T_2 = _io_out_T_1 & io_lhs;
  assign io_out = _io_out_T | _io_out_T_2;
