  wire [3:0] _T = inPipe_bits_fn & 4'h1;
  wire [3:0] _T_2 = inPipe_bits_fn & 4'h2;
  wire  cmdHi = _T == 4'h1 | _T_2 == 4'h2;
  wire  rhsSigned = _T_2 == 4'h0;
