      inPipe_bits_fn <= io_req_bits_fn;
    end
    if (io_req_valid) begin
      inPipe_bits_dw <= io_req_bits_dw;
    end
    if (io_req_valid) begin
      inPipe_bits_in1 <= io_req_bits_in1;
