    end else begin
      io_resp_bits_data_v <= inPipe_valid;
    end
    if (inPipe_valid) begin
      if (cmdHi) begin
        io_resp_bits_data_b <= prod[127:64];
      end else if (cmdHalf) begin
        io_resp_bits_data_b <= _muxed_T_3;
      end else begin
        io_resp_bits_data_b <= prod[63:0];
      end
    end
    if (io_resp_bits_data_v) begin
      io_resp_bits_data_outPipe_bits <= io_resp_bits_data_b;
