    `endif // SYNTHESIS
  end
  always @(posedge clock or posedge ~debug_reset_syncd_debug_reset_sync_io_q) begin
    if (~debug_reset_syncd_debug_reset_sync_io_q) begin
      clock_en <= 1'h1;
    end else begin
      clock_en <= dmactiveAck_dmactiveAck_io_q;
    end
  end
